        let rule = ReadabilityEngine::from_config(&config);
        let source = "function f(a)\n    arguments\n        a (1,1)\n    end\nend\n";
        let diags = lint_nodes(&*rule, source);
        assert!(!has_id(&diags, "FVINR"), "got: {diags:?}");
    }

    #[test]
    fn fvinr_fix_inserts_input_attribute() {
        let source = "function f(a)\n    arguments\n        a (1,1)\n    end\nend\n";
        let diags = lint_nodes(&*engine(), source);
        let diag = diags
            .iter()
            .find(|d| d.rule_id == "FVINR")
            .expect("FVINR should fire");
        let fix = diag.fix.as_ref().expect("FVINR should carry an auto-fix");
        assert_eq!(fix.replacement, " (Input)");
        let mut fixed = String::from(source);
        fixed.replace_range(fix.byte_range.clone(), &fix.replacement);
        assert!(
            fixed.contains("arguments (Input)"),
            "got: {fixed:?}"
        );
    }
}

#!/usr/bin/env python3
"""Mechanical-refactor verification for the readability engine split.

Checks (per the plan):
  1. For each moved `check_*` method, the body extracted from readability.rs is
     byte-identical to the body in the new file except the `pub(crate) ` prefix.
  2. Every check ID is emitted by exactly one file under readability/.
  3. Dispatch calls match: every moved method is dispatched from mod.rs, and
     every `self.check_*` call in mod.rs resolves to a defined method.
  4. Moved-test count + bodies match the original file's test sections.
"""
import re
import sys
from pathlib import Path

ROOT = Path("/home/watermarkhu/repositories/mlt")
SRC = ROOT / "crates/mlt_rules/src/readability.rs"
NEWDIR = ROOT / "crates/mlt_rules/src/readability"

MOVED = [
    "check_isa", "check_stlow", "check_strncmp", "check_strfind",
    "check_char_literal", "check_sprintf", "check_error_warning",
    "check_narginchk", "check_disp", "check_display", "check_prod_size",
    "check_sum_logical", "check_find_logical", "check_fludlr",
    "check_size_comparison", "check_ij_shadow", "check_inline_assignment",
    "check_unnecessary_brackets", "check_comnl", "check_boolean_tautology",
    "check_redundant_arithmetic", "check_fvinr",
]
KEPT = ["check_mfamb", "check_strcmp", "check_function_call", "check_comparison",
        "check_boolean_operator", "check_assignment", "check_binary_operator",
        "check_matrix"]

failures = []


def extract_function(text, name, sig_prefix):
    """Extract full function text (doc comments + signature + body) for
    `<sig_prefix>fn <name>(` via brace counting. Returns the text."""
    lines = text.split("\n")
    fn_line = None
    pat = re.compile(r"fn\s+" + re.escape(name) + r"\s*\(")
    for i, line in enumerate(lines):
        if pat.search(line):
            fn_line = i
            break
    assert fn_line is not None, f"fn {name} not found"

    # include contiguous preceding `///` doc lines
    start = fn_line
    while start > 0 and lines[start - 1].lstrip().startswith("///"):
        start -= 1

    # find the body-open brace (first `{` at/after fn_line)
    depth = 0
    end = None
    for i in range(fn_line, len(lines)):
        for ch in lines[i]:
            if ch == "{":
                depth = 1
                end = i
                break
            if ch == "}":
                raise AssertionError(f"unexpected '}}' before '{{' in {name}")
        if end is not None:
            break
    assert end is not None, f"no body brace for {name}"

    for i in range(end, len(lines)):
        depth += lines[i].count("{") - lines[i].count("}")
        if depth == 0:
            end = i
            break
    return "\n".join(lines[start:end + 1])


def extract_tests(text):
    """Return {test_name: full_test_text} for every #[test] fn in `text`."""
    tests = {}
    lines = text.split("\n")
    for i, line in enumerate(lines):
        if line.strip() != "#[test]":
            continue
        fn_line = i + 1
        m = re.match(r"\s*fn\s+(\w+)\s*\(", lines[fn_line])
        assert m, f"malformed test at line {fn_line}: {lines[fn_line]!r}"
        name = m.group(1)
        # find body-open brace
        depth = 0
        end = None
        for j in range(fn_line, len(lines)):
            for ch in lines[j]:
                if ch == "{":
                    depth = 1
                    end = j
                    break
                if ch == "}":
                    raise AssertionError(f"unexpected '}}' in test {name}")
            if end is not None:
                break
        for j in range(end, len(lines)):
            depth += lines[j].count("{") - lines[j].count("}")
            if depth == 0:
                end = j
                break
        tests[name] = "\n".join(lines[i:end + 1])
    return tests


# ---------------------------------------------------------------- source read
src = SRC.read_text()
new_files = {p.name: p.read_text() for p in sorted(NEWDIR.glob("*.rs"))}

# ------------------------------------------------------------------- 1. bodies
for name in MOVED:
    orig = extract_function(src, name, "fn")
    assert name in new_files, f"missing file for {name}"
    new_text = extract_function(new_files[f"check_{name[6:]}.rs"], name, "pub(crate) fn")
    # normalize the `pub(crate) ` prefix out of the new signature
    new_norm = new_text.replace("pub(crate) fn " + name, "fn " + name, 1)
    if new_norm != orig:
        failures.append(f"BODY MISMATCH: {name}")
        # show first differing line
        o = orig.split("\n")
        n = new_norm.split("\n")
        for k in range(min(len(o), len(n))):
            if o[k] != n[k]:
                failures.append(f"  orig[{k}]: {o[k]!r}")
                failures.append(f"  new [{k}]: {n[k]!r}")
                break
        if len(o) != len(n):
            failures.append(f"  line count orig={len(o)} new={len(n)}")
    else:
        print(f"OK body: {name}")

# ------------------------------------------------- 2. check IDs unique per file
id_re = re.compile(r'((?:self\.diag\(\s*)?"?([A-Z][A-Z0-9]{1,7})"?)')
file_emitted = {}
expected_ids = set()
for fname, text in new_files.items():
    emitted = set()
    # ID as first argument to self.diag(...)
    for m in re.finditer(r"self\.diag\(\s*\"([A-Z][A-Z0-9]{1,7})\"", text, re.S):
        emitted.add(m.group(1))
    # ID in a Diagnostic struct literal
    for m in re.finditer(r"rule_id:\s*\"([A-Z][A-Z0-9]{1,7})\"", text):
        emitted.add(m.group(1))
    # IDs referenced in is_check_enabled / disabled gating inside production code
    for m in re.finditer(r"is_check_enabled\(\s*\"([A-Z][A-Z0-9]{1,7})\"", text):
        expected_ids.add(m.group(1))
    file_emitted[fname] = emitted

dup_ids = set()
all_emitted = {}
for fname, emitted in file_emitted.items():
    for cid in emitted:
        if cid in all_emitted:
            dup_ids.add(cid)
        all_emitted[cid] = fname
if dup_ids:
    failures.append(f"CHECK ID EMITTED FROM MULTIPLE FILES: {sorted(dup_ids)}")
else:
    print(f"OK check-ID uniqueness: {len(all_emitted)} IDs, each emitted once")
    print(f"    IDs: {sorted(all_emitted)}")

# ------------------------------------------------------------------- 3. dispatch
mod_text = new_files["mod.rs"]
for name in MOVED:
    if f"self.{name}(" not in mod_text:
        failures.append(f"DISPATCH MISSING: mod.rs never calls {name}")
print("OK dispatch: every moved method called from mod.rs" if not failures else "dispatch issues")

# every self.check_* call in mod.rs must resolve
defined = set()
for fname, text in new_files.items():
    # strip test modules crudely: find fn names via regex (impl methods + free fns)
    defined |= set(re.findall(r"fn\s+(check_\w+)\s*\(", text))
defined |= set(re.findall(r"fn\s+(check_\w+)\s*\(", src))
for m in re.finditer(r"self\.(check_\w+)\s*\(", mod_text):
    if m.group(1) not in defined:
        failures.append(f"UNRESOLVED CALL in mod.rs: self.{m.group(1)}")

# ------------------------------------------------------------- 4. tests moved
orig_tests = extract_tests(src)
# tests in original, excluding MFAMB/STREMP/STRIFCND (kept in mod.rs)
kept_sections = {"mfamb", "stremp", "strifcnd"}
kept_tests = {k: v for k, v in orig_tests.items() if any(k.startswith(s) for s in kept_sections)}
moved_tests = {k: v for k, v in orig_tests.items() if k not in kept_tests}

new_tests = {}
for fname, text in new_files.items():
    new_tests.update(extract_tests(text))

missing = []
for name, body in moved_tests.items():
    if name not in new_tests:
        missing.append(name)
        continue
    if new_tests[name] != body:
        failures.append(f"TEST BODY MISMATCH: {name}")
if missing:
    failures.append(f"TESTS NOT MOVED: {missing}")

# kept tests must remain in mod.rs
for name, body in kept_tests.items():
    if new_files["mod.rs"].find(body) == -1:
        failures.append(f"KEPT TEST MISSING FROM mod.rs: {name}")

extra = set(new_tests) - set(orig_tests)
if extra:
    failures.append(f"EXTRA TESTS IN NEW FILES: {sorted(extra)}")

print(f"test counts: original={len(orig_tests)} moved={len(moved_tests)} "
      f"kept={len(kept_tests)} in_new_files={len(new_tests)}")

# ------------------------------------------------------------------- summary
print()
if failures:
    print("FAILURES:")
    for f in failures:
        print("  " + f)
    sys.exit(1)
print("ALL VERIFICATIONS PASSED")

result.output:
    // -- STREMP --------------------------------------------------------------

    #[test]
    fn stremp_strcmp_empty_fires() {
        let diags = lint_nodes(&*engine(), "x = strcmp(s, '');\n");
        assert!(has_id(&diags, "STREMP"), "got: {diags:?}");
    }

    #[test]
    fn stremp_strcmp_nonempty_does_not_fire() {
        let diags = lint_nodes(&*engine(), "x = strcmp(s, 'a');\n");
        assert!(!has_id(&diags, "STREMP"), "got: {diags:?}");
    }

    // -- STRIFCND ------------------------------------------------------------

    #[test]
    fn strifcnd_strcmp_in_if_condition_fires() {
        let source = "if strcmp(a, b)\n    x = 1;\nend\n";
        let diags = lint_nodes(&*engine(), source);
        assert!(has_id(&diags, "STRIFCND"), "got: {diags:?}");
    }

    #[test]
    fn strifcnd_strcmp_at_statement_level_does_not_fire() {
        let diags = lint_nodes(&*engine(), "x = strcmp(a, b);\n");
        assert!(!has_id(&diags, "STRIFCND"), "got: {diags:?}");
    }
}
